/**
 * Typed client for the attendance REST API.
 *
 * Each exported object maps 1:1 to a server resource. CRUD-heavy resources are
 * generated by `createCrudAPI` to avoid repeating the same five methods.
 */

import { fetchAPI, postJSON, withQuery } from './http';

/** Ids coming back from SQL Server are integers; older local-fallback paths used strings. */
export type EntityId = string | number;

/** Generic CRUD client factory for `/resource` + `/resource/:id` endpoints. */
export function createCrudAPI<TPayload = any>(resource: string) {
  const base = `/${resource}`;
  return {
    getAll: (filters?: Record<string, unknown>) =>
      fetchAPI(withQuery(base, filters)),
    getById: (id: EntityId) => fetchAPI(`${base}/${id}`),
    create: (data: TPayload) => postJSON(base, data),
    update: (id: EntityId, data: TPayload) => postJSON(`${base}/${id}`, data, 'PUT'),
    delete: (id: EntityId) => fetchAPI(`${base}/${id}`, { method: 'DELETE' }),
  };
}

// Employees API
export const employeesAPI = createCrudAPI('employees');

// Shifts API
export const shiftsAPI = createCrudAPI('shifts');

