// Devices API
export const devicesAPI = {
  ...createCrudAPI('devices'),

  sync: (id: EntityId) => fetchAPI(`/devices/${id}/sync`, { method: 'POST' }),

  /** Undo a soft delete (attendance logs were never removed). */
  restore: (id: EntityId) => fetchAPI(`/devices/${id}/restore`, { method: 'POST' }),

  getLogs: (id: EntityId, limit?: number) =>
    fetchAPI(withQuery(`/devices/${id}/logs`, { limit })),

  getAttendance: (id: EntityId, limit?: number, processed?: boolean) =>
    fetchAPI(withQuery(`/devices/${id}/attendance`, { limit, processed })),

  /** Known device models catalog for the "add device" picker. */
  getCatalog: (filters?: { brand?: string; category?: string; protocol?: string }) =>
    fetchAPI(withQuery('/devices/catalog', filters)),

  /** Protocol registry: { protocols, implemented, drivers } from server (mirrors DB CHECK constraint). */
  getProtocols: () => fetchAPI<{ protocols: string[]; implemented: string[]; drivers: Record<string, boolean> }>('/devices/meta/protocols'),

  /** Catalog coverage stats (brands / protocols / categories). */
  getCatalogStats: () => fetchAPI('/devices/meta/catalog-stats'),

  /** Probe a (possibly unsaved) device configuration. */
  testConnection: (payload: { ipAddress?: string; port?: number; modelId?: string; protocol?: string; config?: Record<string, unknown>; serialNumber?: string }) =>
    postJSON('/devices/test-connection', payload),

  /** Health/reachability snapshot of all devices. */
  getMonitor: () => fetchAPI('/devices/monitor'),

  /** Immediate connectivity check for one saved device. */
  check: (id: EntityId) => fetchAPI(`/devices/${id}/check`, { method: 'POST', timeoutMs: 30_000 }),

  // ---- Phase 2 device control (server enforces `devices.control`) ----

  /** Queue an unlock-open-door command for the device's next contact. */
  unlock: (id: EntityId) => postJSON(`/devices/${id}/unlock`, {}),

  /** Queue a clock-calibration command (device sets its time from server). */
  syncTime: (id: EntityId) => postJSON(`/devices/${id}/sync-time`, {}),

  /** Queue pushing an employee's credentials/user record to the device. */
  pushUser: (id: EntityId, employeeId: EntityId) => postJSON(`/devices/${id}/push-user/${employeeId}`, {}),

  /** Queue deleting a user from the device. */
  deleteUser: (id: EntityId, employeeId: EntityId) => postJSON(`/devices/${id}/delete-user/${employeeId}`, {}),

  /** Queue a "re-pull attendance buffer now" command. */
  refreshData: (id: EntityId) => postJSON(`/devices/${id}/refresh-data`, {}),

  /** Liveness + queue depth snapshot for one device (monitor cards). */
  getStatus: (id: EntityId) => fetchAPI(`/devices/${id}/status`),

  /** Recent queued/delivered/acked control commands for one device. */
  getCommands: (id: EntityId) => fetchAPI(withQuery(`/devices/${id}/commands`, { limit: 50 })),

  /** Mint a fresh webhook token (the old one stops working immediately). */
  rotateSecret: (id: EntityId) => postJSON(`/devices/${id}/rotate-secret`, {}),
};

