// User Roles API — a user may hold multiple roles, each scoped to a unit
export interface RoleAssignment {
  roleId: number;
  roleName: string;
  unitId: number | null; // null = global (valid in every unit)
  unitName: string | null;
  isPrimary: boolean;
}

export const userRolesAPI = {
  /** Returns RoleAssignment[] (role + unit pairs). */
  getUserRoles: (userId: EntityId) => fetchAPI(`/user-roles/${userId}`),

  /** Replace all assignments: [{ roleId, unitId?, isPrimary? }] (unitId omitted/null = global). */
  updateUserRoles: (userId: EntityId, assignments: Array<{ roleId: EntityId; unitId?: EntityId | null; isPrimary?: boolean }>) =>
    postJSON(`/user-roles/${userId}`, { assignments }, 'PUT'),

  assignRole: (userId: EntityId, roleId: EntityId, unitId?: EntityId | null) =>
    postJSON(`/user-roles/${userId}/assign`, { roleId, unitId }),

  revokeRole: (userId: EntityId, roleId: EntityId, unitId?: EntityId | null) =>
    fetchAPI(`/user-roles/${userId}/revoke/${roleId}${unitId != null && unitId !== '' ? `?unitId=${unitId}` : ''}`, { method: 'DELETE' }),

  getEffectivePermissions: (userId: EntityId, unitId?: EntityId | null) =>
    fetchAPI(withQuery(`/user-roles/${userId}/effective`, unitId != null && unitId !== '' ? { unitId } : undefined)),
};

