// ---------------------------------------------------------------------------
// Enrollments API — generic user enrollment (finger / face / card / ...) and
// cross-device transfer. Server: server/routes/enrollments.mjs
// ---------------------------------------------------------------------------

export interface EnrollmentTemplatePayload {
  employeeId: EntityId;
  templateType: 'fingerprint' | 'face' | 'irisscan' | 'palmvein' | 'card' | 'password';
  slot?: string | null;
  value?: string | null;
  algorithm?: string | null;
  quality?: number | null;
  templateBase64?: string | null;
  sourceDeviceId?: EntityId | null;
  status?: 'draft' | 'active' | 'disabled';
  replace?: boolean;
  fileName?: string;
}

export interface EnrollmentDeviceSync {
  deviceId: number;
  deviceName: string;
  syncStatus: 'pending' | 'synced' | 'failed' | 'removed';
  syncMessage: string | null;
  syncedAt: string | null;
}

export interface EnrollmentTemplate {
  id: number;
  employeeId: number;
  employeeName: string | null;
  personnelCode: string | null;
  templateType: string;
  slot: string | null;
  value: string | null;
  algorithm: string | null;
  quality: number | null;
  sourceDeviceId: number | null;
  status: string;
  createdAt: string;
  updatedAt: string;
  size: number;
  devices: EnrollmentDeviceSync[];
}

export interface EnrollmentMetaDevice {
  id: number;
  name: string;
  protocol: string;
  modelId: string | null;
  type: string;
  status: string;
  adapter: string | null;
  /** Credential kinds this hardware can hold (null = unknown/any). */
  capabilities: string[] | null;
}

export interface EnrollmentMeta {
  templateTypes: string[];
  fingerSlots: { id: string; labelFa: string }[];
  adapters: { protocol: string; label: string; supports: string[]; canPush: boolean; canPull: boolean }[];
  devices: EnrollmentMetaDevice[];
}

export interface TransferStepResult {
  deviceId: number;
  templateId: number;
  status: 'success' | 'failed' | 'pending' | 'skipped';
  adapter?: string | null;
  message: string;
  payloadPreview?: string | null;
  payloadLength?: number;
}

export interface TransferOutcome {
  jobId: number;
  status: string;
  totalSteps: number;
  errorCount: number;
  results: TransferStepResult[];
}

export const enrollmentsAPI = {
  /** Capability discovery: credential types, finger slots, transfer adapters, devices. */
  getMeta: () => fetchAPI<EnrollmentMeta>('/enrollments/meta'),

  /** Devices that can enroll/store a credential kind (omit type for all devices). */
  getCapableDevices: (type?: string) =>
    fetchAPI<EnrollmentMeta['devices']>(withQuery('/enrollments/devices', { type })),

  /** Canonical templates with per-device sync matrix. */
  getTemplates: (filters?: { employeeId?: EntityId; type?: string }) =>
    fetchAPI<EnrollmentTemplate[]>(withQuery('/enrollments/templates', filters)),

  /** Save one captured credential (browser capture or import). */
  createTemplate: (payload: EnrollmentTemplatePayload) =>
    postJSON<{ message: string; id: number }>('/enrollments/templates', payload),

  deleteTemplate: (id: EntityId) => fetchAPI(`/enrollments/templates/${id}`, { method: 'DELETE' }),

  /** Push one template to selected devices (dryRun builds payloads without touching devices). */
  transferTemplate: (id: EntityId, deviceIds: EntityId[], dryRun = false) =>
    postJSON<TransferOutcome>(`/enrollments/templates/${id}/transfer`, { deviceIds, dryRun }, 'POST'),

  /** Bulk push: all templates of an employee, or explicit template ids. */
  transfer: (payload: { employeeId?: EntityId; templateIds?: EntityId[]; deviceIds: EntityId[]; dryRun?: boolean }) =>
    postJSON<TransferOutcome>('/enrollments/transfer', payload),

  /** Import templates that already exist on a device into the canonical store. */
  pull: (deviceId: EntityId, userId?: string) =>
    postJSON<{ ok: boolean; pulled?: number; imported?: number; skippedUnknownUser?: number; error?: string }>('/enrollments/pull', { deviceId, userId }),

  getJobs: (limit?: number) => fetchAPI(withQuery('/enrollments/jobs', { limit })),
  getJob: (id: EntityId) => fetchAPI(`/enrollments/jobs/${id}`),
};

// Health check
export const healthCheck = () => fetchAPI('/health');
